// workerRegistry.mjs
const activeWorkers = new Set();

export function registerWorker(worker) {
  activeWorkers.add(worker);
  worker.on('exit', () => activeWorkers.delete(worker));
}

export function getActiveWorkers() {
  return Array.from(activeWorkers);
}

export async function shutdownWorkers() {
  const tasks = [];

  for (const worker of activeWorkers) {
    const p = (async () => {
      try {
        await worker.terminate();
      } catch (err) {
        console.warn('[raft-logic][warn] Failed to terminate worker:', err);
      } finally {
        try {
          if (typeof worker.unref === 'function') {
            worker.unref();
          }
        } catch (_e) {
          // ignore unref errors
        }
      }
    })();
    tasks.push(p);
  }

  if (tasks.length) {
    await Promise.allSettled(tasks);
  }

  activeWorkers.clear();
}

/**
 * Clears all registered workers without terminating them.
 * Useful for test isolation between clusters.
 */
export function clearWorkerRegistry() {
  activeWorkers.clear();
}
